/**
 * A species on the Ark map (B3): its spawn tag, the tags it may stand on,
 * how it moves, what it holds to, where it sleeps, its partner role and its
 * colony, from `species.json` (generated by `scripts/ark-map.mts` from stored
 * text; every reason in `docs/ark-map/species.json`).
 *
 * A model the table does not list (a breed, A1; a species added since) takes
 * its zone's fallback tag, like the no-text species (decision 5).
 */

import table from "@/ark-scene/map/species.json";
import {speciesLayer} from "@/ark-scene/layers";
import {MAP_ATTACHMENTS, MAP_MOVES, MAP_TAGS, type HostGroup, type MapAttachment, type MapMove, type MapRole, type MapTag} from "@/ark-scene/map/tags";
import {ARK_ZONES, type ArkZone} from "@/ark-scene/types";
import type {ArkActivity} from "@/lib/ark-daylight";
import holds from "@/ark-scene/map/validator-holds.json";

type Row = [number, string, number, number, number, string, string, string, number, string];
const TABLE = table as unknown as {held: string[]; hosts: Record<HostGroup, {ids: string[]; slugs: string[]}>; points: Record<string, Record<string, number>>; species: Record<string, Row>};

export type MapSpecies = {
    spawn: MapTag;
    /** Every tag it may stand on (its microhabitats, its nest, its roost): each from a stored phrase. */
    allowed: ReadonlySet<MapTag>;
    move: MapMove;
    attach: MapAttachment;
    /** Where it sleeps when that is not where it lives (from `sleep_pattern`). */
    roost: MapTag | null;
    role: MapRole | null;
    host: HostGroup | null;
    colony: boolean;
    /** Size stat at or below 15 (about a brown rat): it sits on the scenery's attach points. */
    small: boolean;
    /** Placed by its zone (no text, or not in the table). */
    fallback: boolean;
};

/** The validator's reviewed hold list (`validator-holds.json`): species it cannot place well on this terrain yet, each with its reason. */
const REVIEWED = (holds as unknown as {species: Record<string, string>}).species;
const HELD = new Set([...TABLE.held, ...Object.keys(REVIEWED)]);
const known = new Map<string, MapSpecies | null>();

/** Decision 2 (the Antarctic ones) and the host-absent head louse: never placed on the map. */
export function isHeldOnMap(slug: string): boolean {
    return HELD.has(slug);
}

function fallbackTag(zone: ArkZone, slug: string): MapTag {
    const layer = speciesLayer(slug);
    switch (zone) {
        case "coral_reef": return "coral_reef";
        case "open_ocean": return layer.layer === "deep" ? "deep_water" : "open_ocean";
        case "seashore": return layer.layer === "reef" || layer.layer === "open_sea" ? "coastal_shallows" : "sandy_beach";
        case "river_lake": return "lake";
        case "wetland": return "marsh_reeds";
        case "rainforest":
        case "woodland": return layer.layer === "canopy" ? "canopy" : "forest_floor";
        case "grassland": return "grassland";
        case "desert": return "desert_sand";
        case "mountains": return "mountain_alpine";
        case "polar": return "tundra";
        default: return "garden";
    }
}

/** A species' map entry; `zone` is only for one the table does not list. Null when it is held. */
export function mapSpecies(slug: string, zone: ArkZone): MapSpecies | null {
    const key = `${slug}#${zone}`;
    if (known.has(key)) return known.get(key)!;
    let out: MapSpecies | null;
    const row = TABLE.species[slug];
    if (HELD.has(slug)) out = null;
    else if (row) {
        const flags = row[7];
        out = {
            spawn: MAP_TAGS[row[0]],
            allowed: new Set(row[1].split(".").map((i) => MAP_TAGS[Number(i)])),
            move: MAP_MOVES[row[2]],
            attach: MAP_ATTACHMENTS[row[3]],
            roost: row[4] >= 0 ? MAP_TAGS[row[4]] : null,
            role: (row[5] || null) as MapRole | null,
            host: (row[6] || null) as HostGroup | null,
            colony: flags.includes("c"),
            small: flags.includes("s"),
            fallback: flags.includes("z")
        };
    } else {
        const tag = fallbackTag(zone, slug);
        const layer = speciesLayer(slug);
        const sea = zone === "coral_reef" || zone === "open_ocean";
        out = {
            spawn: tag,
            allowed: new Set([tag]),
            move: sea ? "swim" : layer.layer === "canopy" ? "climb" : "walk",
            attach: sea ? "water" : layer.layer === "canopy" ? "limb" : "ground",
            roost: null,
            role: null,
            host: null,
            colony: false,
            small: false,
            fallback: true
        };
    }
    known.set(key, out);
    return out;
}

/** Is this animal (its model slug, its kind's species id) one of the host group? Breeds count as their kind (A1). */
export function isHost(group: HostGroup, slug: string, kindId: string | null | undefined, speciesId: string): boolean {
    const hosts = TABLE.hosts[group];
    if (!hosts) return false;
    return hosts.slugs.includes(slug) || hosts.ids.includes(speciesId) || Boolean(kindId && hosts.ids.includes(kindId));
}

/** The launch points (decision 6): per spawn tag, per zone. */
export function launchPoints(): Record<string, Record<string, number>> {
    return TABLE.points;
}

/** The table's voyage zone and stored activity of a species (for the validator; the scene has the server's). */
export function mapSpeciesStored(slug: string): {zone: ArkZone; activity: ArkActivity | null} | null {
    const row = TABLE.species[slug];
    return row ? {zone: ARK_ZONES[row[8]] ?? "farm_garden", activity: (row[9] || null) as ArkActivity | null} : null;
}

/** The decision-2 holds and the validator's reviewed holds, with why. */
export function mapHolds(): {decision: string[]; reviewed: Record<string, string>} {
    return {decision: TABLE.held, reviewed: REVIEWED};
}

/** Every listed slug (for the tests and the probes). */
export function mapSlugs(): string[] {
    return Object.keys(TABLE.species);
}
